// 原领读本人按作者意向有限托回；不用当前远方人/未领答复当路由或新承诺。
#include "visit_reply_director.hpp"
#include "visit_reply_detail.hpp"
#include "resident/kernel/command_types.hpp"
#include "resident/domains/tasks/task_model.hpp"
namespace hanmo::resident {namespace {
using Result=Outcome<std::optional<DecisionProposal>>;
struct Pending {const VisitReplyIntent* intent=nullptr;const VisitReplyPolicy* policy=nullptr;const VisitMessageTerminal* received=nullptr;};
Outcome<Pending> pending(const VisitReceptionRead& r,const VisitReplyNpcRead& n,const StableId& actor,const StableId& reception_id){auto valid=validate_visit_reply_intents(n.intents,n.catalog,r.catalog,r.message_catalog,r.interaction_catalog);if(!valid.ok)return {false,{},valid.error};if(!visit_reply_authored_version(n.state.version))return {false,{},common_failure("VisitReplyAuthoredVersionRequired").error};const auto* original=visit_reception_intent(r.catalog,reception_id);const auto* intent=visit_reply_reception_intent(n.intents,reception_id);if(!intent)return {true,{}, {}};const auto* policy=visit_reply_detail::policy(n.catalog,intent->reply_policy_id);if(!original||original->actor_id!=actor||!policy)return {false,{},common_failure("VisitReplyAuthoredIntentRequired",reception_id).error};
    for(const auto& row:r.messages.received.rows())if(row.second.contact.actor_id==actor){const auto* message=r.messages.posted.find(row.second.message_fact_id);if(message&&message->policy_id==policy->message_policy_id&&!visit_reply_detail::replied(n.state,message->fact_id))return {true,{intent,policy,&row.second},{}};}return {true,{}, {}};}
DirectorTransition& transition(DecisionProposal& p){return const_cast<DirectorTransition&>(*p.transition);}
Result original_interaction(const VisitReceptionRead& r,DecisionProposal p,const StableId& kind,const InteractionCommand& command){auto preview=preview_interaction(r.common,r.interactions,r.interaction_catalog,r.access,p.subject_id,command);if(!preview.ok){if(preview.error.kind!=ErrorKind::rule)return {false,{},preview.error};return {true,std::nullopt,{}};}p.command=std::make_shared<const CommandPayload>(CommandPayload{kind,command});return {true,std::move(p),{}};}
}
Outcome<bool> visit_reply_reception_pending(const VisitReceptionRead& r,const VisitReplyNpcRead& n,const StableId& actor,const StableId& intent){auto source=pending(r,n,actor,intent);return source.ok?Outcome<bool>{true,source.value.received!=nullptr,{}}:Outcome<bool>{false,{},source.error};}
Result propose_received_visit_reply(const VisitReceptionRead& r,const VisitReplyNpcRead& n,const DirectorState& director,const KnownSubjectView& view,const StableId& reception_id,const DecisionProposal& original){
    if(!original.transition||original.subject_id!=view.actor_id||view.subject.kind!=SubjectKind::actor||view.subject.id!=view.actor_id||view.tick!=r.common.tick()||view.revision!=r.common.revision()||original.transition->expected_revision!=r.common.revision())return {false,{},common_failure("InvalidVisitReplyDirectorInput").error};
    if(!view.alive||!view.available||!view.current_action_id.empty()||original.transition->pending_life_action_id)return {true,std::nullopt,{}};
    for(const auto& task:r.tasks.tasks.rows())if(task.second.assignee==view.actor_id&&(task.second.status=="accepted"||task.second.status=="active"||task.second.status=="in_progress"||task.second.status=="ready"||task.second.status=="settling"))return {true,std::nullopt,{}};
    // 先确认本模板实际认领的现场，才查看这个人的真实已领原件。
    auto ready=visit_reception_conversation_ready(r,director,view.actor_id,reception_id);if(!ready.ok)return {false,{},ready.error};if(!ready.value)return {true,std::nullopt,{}};const InteractionSession* session=nullptr;for(const auto& s:r.interactions.interactions)if(s.actor_id==view.actor_id){if(session)return {false,{},common_failure("VisitReplyAmbiguousSession").error};session=&s;}if(!session||session->pending_command)return {true,std::nullopt,{}};
    auto source=pending(r,n,view.actor_id,reception_id);if(!source.ok)return {false,{},source.error};if(!source.value.received)return {true,std::nullopt,{}};const auto& p=source.value;const auto* reception=visit_reception_intent(r.catalog,reception_id);const auto* message=visit_reply_detail::original(r.message_catalog,p.policy->message_policy_id);const auto* role=message?r.interaction_catalog.common->roles.find(message->role_id):nullptr;auto location=r.common.resolved_location(view.actor_id);const auto* here=location.ok?std::get_if<SettlementLocation>(&location.value):nullptr;if(!reception||!message||!role||!here||here->place_id!=role->place_id||view.place_id!=here->place_id)return {true,std::nullopt,{}};
    const auto* claim=read_visit_reception_claim(r.claims,session->id,view.actor_id,reception_id);if(!claim)return {true,std::nullopt,{}};DecisionProposal proposal=original;proposal.transition=std::make_shared<DirectorTransition>(*original.transition);auto& next=transition(proposal);next.template_id="visit_reception";next.goal_ref=session->id;next.phase=PlanPhase::accepting;next.current_action_id.reset();next.commitment_ids.clear();next.wait_reason.clear();next.next_step_index=static_cast<Integer>(reception->route.size()+1);proposal.command.reset();
    if(session->node_id!=p.policy->reply_node_id){const VisitReceptionStep* step=nullptr;for(const auto* route:{&p.intent->route,&reception->route}){for(const auto& candidate:*route)if(candidate.node_id==session->node_id){step=&candidate;break;}if(step)break;}if(!step)return {true,std::nullopt,{}};return step->option_id.empty()?original_interaction(r,std::move(proposal),"dialogue_next",DialogueNext{}):original_interaction(r,std::move(proposal),"dialogue_choose",DialogueChoose{step->option_id});}
    VisitReplyAuthorshipRead legacy{n.intents,r.catalog,r.claims,r.interactions};if(visit_reply_life_version(n.state.version)&&(!n.original||!n.original->authorship))return {false,{},common_failure("VisitReplyActualAuthorshipReadRequired",{},ErrorKind::unsupported_capability).error};const auto&read=n.original?*n.original->authorship:legacy;AuthoredVisitReply command{p.intent->id,p.received->message_fact_id,p.received->fact_id,claim->fact_id};auto quote=preview_authored_visit_reply(r.common,r.messages,r.message_catalog,r.interaction_catalog,r.access,n.catalog,n.state,read,view.actor_id,command);if(!quote.ok){if(quote.error.kind!=ErrorKind::rule)return {false,{},quote.error};return {true,std::nullopt,{}};}next.phase=PlanPhase::completed;proposal.command=std::make_shared<const CommandPayload>(CommandPayload{authored_visit_reply_command,std::move(command)});return {true,std::move(proposal),{}};
}
}
